package com.integration.controller;

import com.integration.service.WebhookService;
import lombok.RequiredArgsConstructor;
import lombok.extern.log4j.Log4j2;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.Map;

@RestController
@Log4j2
@RequestMapping("/webhook")
@RequiredArgsConstructor
public class WebhookController {

    private final WebhookService webhookService;

    @Value("${webhook.security.key}")
    private String securityKey;

    @PostMapping("/leadsquared/leaddetails")
    public ResponseEntity<String> receiveWebhook(
            @RequestHeader(value = "X-Webhook-Token", required = false) String token,
            @RequestBody Map<String, Object> payload) {
        log.info("Incoming webhook request");

        if (token == null || !token.equals(securityKey)) {
            log.warn("Unauthorized webhook request attempt");
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body("Unauthorized");
        }

        webhookService.handleWebhook(payload);
        return ResponseEntity.ok("Webhook received successfully");
    }
}

