package com.integration.service.solar.impl;

import com.integration.service.SapService;
import com.integration.service.solar.SolarLeadSquaredService;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.ArgumentCaptor;
import org.mockito.Captor;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.http.ResponseEntity;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyList;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class SolarLeadServiceImplTest {

    @Mock
    private SolarLeadSquaredService solarLeadSquaredService;

    @Mock
    private SapService sapService;

    @InjectMocks
    private SolarLeadServiceImpl solarLeadService;

    @Captor
    private ArgumentCaptor<Map<String, Object>> leadDataCaptor;

    @Test
    void shouldProcessLeadAndCreateSapCustomerWhenStageIsDealConverted() throws Exception {
        // Arrange
        Map<String, Object> lead = buildLead("prospect-001", "Deal Converted", "", "John", "9876543210");
        Map<String, Object> lsqResponse = Map.of("Leads", List.of(lead));
        when(solarLeadSquaredService.getLeadsInBulkByIds(anyList()))
                .thenReturn(ResponseEntity.ok(lsqResponse));
        when(sapService.createCustomer(any())).thenReturn(buildSapSuccessResponse("SAP-001"));

        // Act
        boolean result = solarLeadService.processLeadIds(List.of("prospect-001"));

        // Assert
        assertThat(result).isTrue();
        verify(sapService).createCustomer(leadDataCaptor.capture());
        Map<String, Object> capturedData = leadDataCaptor.getValue();
        assertThat(capturedData.get("ProspectID")).isEqualTo("prospect-001");
        assertThat(capturedData.get("Name")).isEqualTo("John");
        assertThat(capturedData.get("Mobile")).isEqualTo("9876543210");
    }

    @Test
    void shouldUpdateLeadInLsqWithSapCodeAfterSuccessfulCreation() throws Exception {
        // Arrange
        Map<String, Object> lead = buildLead("prospect-002", "Deal Converted", "", "Jane", "9123456780");
        Map<String, Object> lsqResponse = Map.of("Leads", List.of(lead));
