package com.integration.controller.solar;

import com.integration.service.solar.SolarLeadService;
import lombok.RequiredArgsConstructor;
import lombok.extern.log4j.Log4j2;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.web.bind.annotation.*;

import java.util.*;

@RestController
@Log4j2
@RequestMapping("/leads")
@RequiredArgsConstructor
public class SolarLeadController {

    @Autowired
    SolarLeadService solarLeadService;

    @GetMapping(value = "/runLeadWorkflowDateWise")
    public Object runLeadWorkflow(@RequestParam @DateTimeFormat(pattern = "yyyy-MM-dd HH:mm:ss") Date fromDate,
                                  @RequestParam @DateTimeFormat(pattern = "yyyy-MM-dd HH:mm:ss") Date toDate) throws Exception {
        boolean response = solarLeadService.processLeads(fromDate, toDate);
        return response;
    }

    @GetMapping(value = "/createSapCustomer")
    public Object createSapCustomer() throws Exception {
        Map<String, Object> response = solarLeadService.createSapCustomer();
        return response;
    }

    @PostMapping(value = "/processLeadIds")
    public Object getLeadsInBulkByIds(@RequestBody Map<String, List<String>> body) throws Exception {
        List<String> leadIds = body.get("leadIds");
        boolean success = solarLeadService.processLeadIds(leadIds);
        return success;
    }
}

